"""Emit boundary stencils without changing the ordinary differential header."""

from __future__ import annotations

from .emit_spatial_order import spatial_order_assertion_cpp

from .differential_equations import (
    forward_difference_weights,
    one_sided_stencils,
)
from .numerical_catalog import SPATIAL_ORDERS


def render_boundary_differential_header() -> str:
    # Imported at call time to share the one numeric printer without a cycle.
    from .emit_cpp import _fd_weight

    lines = [
        "#pragma once",
        "",
        "// Generated by generate_kernels.py; do not edit by hand.",
        "#include <AMReX_Algorithm.H>",
        "#include <AMReX_Array.H>",
        '#include "pyfluid_amrex/kernels_generated/differential_ops.hpp"',
        "",
        "namespace pyfluid_amrex::generated {",
        "",
        "using namespace amrex::literals;",
    ]
    for derivative, name in ((1, "first"), (2, "second")):
        lines.extend([
            "",
            "template <int Order, int Direction, typename Array>",
            "AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE",
            f"amrex::Real one_sided_{name}(Array const& field, int i, int j, int k,",
            "   int component, int side, amrex::Real scale) noexcept",
            "{",
            spatial_order_assertion_cpp(),
        ])
        for index, (_backward, forward) in enumerate(one_sided_stencils(derivative)):
            prefix = "if" if index == 0 else "else if"
            weights = ", ".join(_fd_weight(w) for w in forward.weights)
            lines.extend([
                f"   {prefix} constexpr (Order == {forward.order}) {{",
                f"      constexpr amrex::Real weights[]{{{weights}}};",
                "      const amrex::Real center = field(i, j, k, component);",
                "      amrex::Real result = 0.0_rt;",
                f"      for (int offset = 1; offset < {len(forward.offsets)}; ++offset) {{",
                "         result += weights[offset] * (sample_direction<Direction>(",
                "            field, i, j, k, component, side * offset) - center);",
                "      }",
                "      return scale * result" + (" * side;" if derivative == 1 else ";"),
                "   }",
            ])
        lines.extend(["   return 0.0_rt;", "}"])

    lines.extend([
        "",
        "template <int Order, int Direction1, int Direction2, typename Array>",
        "AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE",
        "amrex::Real one_sided_mixed(Array const& field, int i, int j, int k,",
        "   int component, int side1, int side2, amrex::Real scale) noexcept",
        "{",
        spatial_order_assertion_cpp(),
        "   static_assert(Direction1 != Direction2);",
    ])
    for index, (_backward, forward) in enumerate(one_sided_stencils()):
        prefix = "if" if index == 0 else "else if"
        weights = ", ".join(_fd_weight(w) for w in forward.weights)
        lines.extend([
            f"   {prefix} constexpr (Order == {forward.order}) {{",
            f"      constexpr amrex::Real weights[]{{{weights}}};",
            "      const amrex::Real center = field(i, j, k, component);",
            "      amrex::Real result = 0.0_rt;",
            "      for (int a = 1; a <= Order; ++a) {",
            "         const amrex::Real axis1 = sample_direction<Direction1>(",
            "            field, i, j, k, component, side1 * a);",
            "         for (int b = 1; b <= Order; ++b) {",
            "            const amrex::Real axis2 = sample_direction<Direction2>(",
            "               field, i, j, k, component, side2 * b);",
            "            result += weights[a] * weights[b]",
            "               * ((sample_directions<Direction1, Direction2>(",
            "                  field, i, j, k, component, side1 * a, side2 * b) - axis1)",
            "                  - (axis2 - center));",
            "         }",
            "      }",
            "      return scale * side1 * side2 * result;",
            "   }",
        ])
    lines.extend(["   return 0.0_rt;", "}"])

    lines.extend([
        "",
        "// Q = -D_+^T W D_+ / 2^(2r), with W=0 for factors touching",
        "// inactive points. This retains nonpositive discrete energy at an",
        "// irregular boundary; it is ordinary centered KO away from it.",
        "template <int Order, int Direction, typename Array, typename Mask>",
        "AMREX_GPU_HOST_DEVICE AMREX_FORCE_INLINE",
        "amrex::Real masked_kreiss_oliger(Array const& field, Mask const& active,",
        "   int i, int j, int k, int component, amrex::Real inv_spacing) noexcept",
        "{",
        spatial_order_assertion_cpp(),
        "   if (!active(i, j, k, 0)) return 0.0_rt;",
    ])
    for index, order in enumerate(SPATIAL_ORDERS):
        degree = order // 2 + 1
        weights = ", ".join(_fd_weight(w) for w in forward_difference_weights(degree))
        prefix = "if" if index == 0 else "else if"
        lines.extend([
            f"   {prefix} constexpr (Order == {order}) {{",
            f"      constexpr int degree = {degree};",
            f"      constexpr amrex::Real weights[]{{{weights}}};",
            "      amrex::Real result = 0.0_rt;",
            "      for (int position = 0; position <= degree; ++position) {",
            "         bool factor_active = true;",
            "         for (int offset = 0; offset <= degree; ++offset) {",
            "            factor_active = factor_active && sample_direction<Direction>(",
            "               active, i, j, k, 0, offset - position) != 0.0_rt;",
            "         }",
            "         if (!factor_active) continue;",
            "         amrex::Real difference = 0.0_rt;",
            "         for (int offset = 0; offset <= degree; ++offset) {",
            "            difference += weights[offset] * sample_direction<Direction>(",
            "               field, i, j, k, component, offset - position);",
            "         }",
            "         result -= weights[position] * difference;",
            "      }",
            f"      return inv_spacing * result / {2 ** (2 * degree)}.0_rt;",
            "   }",
        ])
    lines.extend([
        "   return 0.0_rt;", "}", "",
        "} // namespace pyfluid_amrex::generated", "",
    ])
    return "\n".join(lines)
